void getDataFromThread2(std::vector<uint8_t>& data)
{
    DWORD data_len = 0;
    DWORD len = sizeof(DWORD);
    
    BOOL success = FALSE;
    
    HANDLE fmOut = CreateFileMapping(
                                     INVALID_HANDLE_VALUE,
                                     NULL,
                                     PAGE_READWRITE,
                                     0, len,
                                     L"TWAIN_PARAM_OUT");
    if (fmOut)
    {
        LPVOID bufOut = MapViewOfFile(fmOut, FILE_MAP_READ, 0, 0, len);
        if (bufOut)
        {
            unsigned char *p = (unsigned char *)bufOut;
            try
            {
                CopyMemory(&data_len, p, sizeof(DWORD));
                success = TRUE;
            }
            catch (...)
            {
                
            }
            UnmapViewOfFile(bufOut);
        }
        CloseHandle(fmOut);
    }
    if ((success) && (data_len))
    {
        len = len + data_len;
        
        fmOut = CreateFileMapping(
                                  INVALID_HANDLE_VALUE,
                                  NULL,
                                  PAGE_READWRITE,
                                  0, len,
                                  L"TWAIN_PARAM_OUT");
        if (fmOut)
        {
            LPVOID bufOut = MapViewOfFile(fmOut, FILE_MAP_READ, 0, 0, len);
            if (bufOut)
            {
                unsigned char *p = (unsigned char *)bufOut;
                p = p + sizeof(DWORD);
                try
                {
					data.resize(data_len);
                    CopyMemory((void *)&data[0], p, data_len);
                }
                catch (...)
                {
                    
                }
                UnmapViewOfFile(bufOut);
            }
            CloseHandle(fmOut);
        }
        
    }
    
}

void waitForEvent(HANDLE h, HANDLE scanEvent_p, std::vector<uint8_t>& data, std::wstring& ParamB, DWORD len)
{
    /*
     FIX: also wait on the worker thread handle; previously, if the worker
     ended without signalling scanEvent_p, this loop never ended.
     */
    HANDLE handles[2] = {scanEvent_p, h};
    BOOL exit = FALSE;
    
    do {
        switch (WaitForMultipleObjects(2, handles, FALSE, 100))
        {
            case WAIT_OBJECT_0:
            {
                /* response is ready */
                ResetEvent(scanEvent_p);
                
                getDataFromThread2(data);
                
                HANDLE scanEvent_c = OpenEvent(EVENT_ALL_ACCESS, FALSE, ParamB.c_str());
                if(scanEvent_c)
                {
                    /* tell c to die */
                    SetEvent(scanEvent_c);
                    CloseHandle(scanEvent_c);
                }
                exit = TRUE;
            }
                break;
            case WAIT_OBJECT_0 + 1:
                /* worker ended without a response */
                exit = TRUE;
                break;
            case WAIT_TIMEOUT:
                PA_YieldAbsolute();
                break;
            default:
                /* WAIT_FAILED, WAIT_ABANDONED_* */
                exit = TRUE;
                break;
        }
        
    } while (!exit);
    
    /*
     FIX: always let the worker finish before returning;
     it reads twain_version_info_t from the caller's stack
     */
    while (WAIT_TIMEOUT == WaitForSingleObject(h, 100))
    {
        PA_YieldAbsolute();
    }
}

